@TwoLevelMeasure.mixed_bind_ae_proper
     : forall (MN MF : Type -> Type) (NI : TwoLevelMeasure.SemanticMeasure MN)
         (FI : TwoLevelMeasure.SemanticMeasure MF) (MX : TwoLevelMeasure.MixedMeasure MN MF),
       @TwoLevelMeasure.MixedMeasureLaws MN MF NI FI MX ->
       forall (A B : Type) (mu : MN A) (k h : A -> MF B),
       @TwoLevelMeasure.sem_ae MN NI A mu
         (fun x : A => @TwoLevelMeasure.sem_eq MF FI B (k x) (h x)) ->
       @TwoLevelMeasure.sem_eq MF FI B (@TwoLevelMeasure.mixed_bind MN MF MX A B mu k)
         (@TwoLevelMeasure.mixed_bind MN MF MX A B mu h)

