       forall (A B C : Type) (mu : MN A) (k : A -> MF B) (h : B -> MF C),
       @TwoLevelMeasure.sem_eq MF FI C
         (@TwoLevelMeasure.sem_bind MF FI B C (@TwoLevelMeasure.mixed_bind MN MF MX A B mu k) h)
         (@TwoLevelMeasure.mixed_bind MN MF MX A C mu
            (fun x : A => @TwoLevelMeasure.sem_bind MF FI B C (k x) h))

@TwoLevelMeasure.mixed_lift_bind
     : forall (MN MF : Type -> Type) (NI : TwoLevelMeasure.SemanticMeasure MN)
         (FI : TwoLevelMeasure.SemanticMeasure MF) (MX : TwoLevelMeasure.MixedMeasure MN MF),
       @TwoLevelMeasure.MixedMeasureLaws MN MF NI FI MX ->
       forall (A B C D : Type) (R : A -> B -> Prop) (T : C -> D -> Prop)
         (mu : MN A) (nu : MN B) (k : A -> MF C) (h : B -> MF D),
       @TwoLevelMeasure.sem_lift MN NI A B R mu nu ->
       (forall (x : A) (y : B), R x y -> @TwoLevelMeasure.sem_lift MF FI C D T (k x) (h y)) ->
       @TwoLevelMeasure.sem_lift MF FI C D T (@TwoLevelMeasure.mixed_bind MN MF MX A C mu k)
         (@TwoLevelMeasure.mixed_bind MN MF MX B D nu h)

@TwoLevelMeasure.mixed_bind_ret_l
     : forall (MN MF : Type -> Type) (NI : TwoLevelMeasure.SemanticMeasure MN)
         (FI : TwoLevelMeasure.SemanticMeasure MF) (MX : TwoLevelMeasure.MixedMeasure MN MF),
       @TwoLevelMeasure.MixedMeasureUnitLaws MN MF NI FI MX ->
       forall (A B : Type) (x : A) (k : A -> MF B),
       @TwoLevelMeasure.sem_lift MF FI B B (@eq B)
         (@TwoLevelMeasure.mixed_bind MN MF MX A B (@TwoLevelMeasure.sem_ret MN NI A x) k)
         (k x)

