     : forall (MN MF : Type -> Type) (NI : TwoLevelMeasure.SemanticMeasure MN)
         (FI : TwoLevelMeasure.SemanticMeasure MF) (MX : TwoLevelMeasure.MixedMeasure MN MF),
       @TwoLevelMeasure.MixedMeasureNodeBindLaws MN MF NI FI MX ->
       forall (A B C : Type) (mu : MN A) (h : A -> MN B) (k : B -> MF C),
       @TwoLevelMeasure.sem_lift MF FI C C (@eq C)
         (@TwoLevelMeasure.mixed_bind MN MF MX A C mu
            (fun x : A => @TwoLevelMeasure.mixed_bind MN MF MX B C (h x) k))
         (@TwoLevelMeasure.mixed_bind MN MF MX B C (@TwoLevelMeasure.sem_bind MN NI A B mu h) k)

