       (forall n : nat, @TwoLevelMeasure.sem_eq S SI A (chain n) (chain' n)) ->
       @TwoLevelMeasure.sem_lub S SI SO A chain mu ->
       @TwoLevelMeasure.sem_lub S SI SO A chain' nu -> @TwoLevelMeasure.sem_eq S SI A mu nu

