       forall (A : Type) (chain chain' : nat -> S A) (mu : S A),
       (forall n : nat, @TwoLevelMeasure.sem_eq S SI A (chain n) (chain' n)) ->
       @TwoLevelMeasure.sem_lub S SI SO A chain mu -> @TwoLevelMeasure.sem_lub S SI SO A chain' mu

