     : forall (S : Type -> Type) (SI : TwoLevelMeasure.SemanticMeasure S)
         (SO : @TwoLevelMeasure.SemanticOmega S SI),
       @TwoLevelMeasure.SemanticOmegaLaws S SI SO ->
       forall (A B : Type) (chain : nat -> S A) (mu : S A) (k : A -> S B),
       @TwoLevelMeasure.sem_increasing S SI SO A chain ->
       @TwoLevelMeasure.sem_lub S SI SO A chain mu ->
       @TwoLevelMeasure.sem_lub S SI SO B
         (fun n : nat => @TwoLevelMeasure.sem_bind S SI A B (chain n) k)
         (@TwoLevelMeasure.sem_bind S SI A B mu k)

